import { Component, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { IonicStorageService } from 'src/app/services/ionic-storage/ionic-storage.service';
import { HttpClient } from '@angular/common/http';
import { environment } from 'src/environments/environment';
@Component({
  selector: 'app-ca-student-details',
  templateUrl: './ca-student-details.page.html',
  styleUrls: ['./ca-student-details.page.scss'],
})
export class CaStudentDetailsPage implements OnInit {
  routeData: any;
  title: any;
  mode: any;
  zonelId: any;
  schoolName: any;
  studentData: any;
  SchoolId: number;
  EMISNo: any;
  Class: any;
  Section: any;
  disType: any;
  studId: any;
  studName: any;
  menuValue: any = '';
  cwsnDiffAbleList: any = [];
  classMap: any = { 1: 'I', 2: 'II', 3: 'III', 4: 'IV', 5: 'V', 6: 'VI', 7: 'VII', 8: 'VIII', 9: 'IX', 10: 'X', 11: 'XI', 12: 'XII', 13: 'LKG', 14: 'UKG', 15: 'PRE-KG' };

  constructor(
    private router: Router,
    private route: ActivatedRoute,
    private ionicstorage: IonicStorageService,
    private http: HttpClient
  ) { }

  ngOnInit() {

  }

  ionViewDidEnter() {
    this.route.queryParams.subscribe(data => {
      this.studentData = JSON.parse(data.item);
      console.log('queryParams', this.studentData);
      this.zonelId = this.studentData.ZonalId
      this.schoolName = this.studentData.SchlNme;
      this.SchoolId = parseInt(this.studentData.SchlId);
      this.EMISNo = this.studentData.EMIS_No;
      this.Class = this.studentData.Class;
      this.Section = this.studentData.Section;
      this.studId = this.studentData.studId;
      this.studName = this.studentData.Name;
      this.menuValue = data.menuValue;
      this.ionicstorage.insertData_Replace('studentData', this.studentData);
      this.ionicstorage.getData('studentData').then(
        (studData) => {
          console.log('studData', studData)
        })
      this.loadDisability(this.studentData.screen_disability);
    })

    this.routeData = this.route.snapshot;
    this.title = this.routeData.queryParams.title;
    this.mode = this.routeData.queryParams.mode;
    console.log('title', this.title, 'mode', this.mode);

    // ====schoollist data check in local db======
    // this.checkLocalDB();
  }

  goBack() {
    this.router.navigate(['/tabs/ca-student-list'], { queryParams: { item: JSON.stringify(this.studentData), menuValue: this.menuValue, 'zonleId': this.zonelId, title: this.title, mode: this.mode } });
  }

  goToDomainList() {
    this.router.navigate(["/tabs/ca-domain-list"], { queryParams: { title: this.title, mode: this.mode } });
  }

  loadDisability(disabily) {
    // let url = 'https://d1wpyxz35bzzz4.cloudfront.net/diff-abled/baseapp_diff_able_json.json';
    this.ionicstorage.getData('cwsn_diff_able_json').then(
      (data) => {
        if (!data) {
          this.http.get<any>(environment.cwsn_diff_able_json).subscribe((data: any) => {
            this.calcDisability(data.cwsn_diff_able, disabily);
            this.ionicstorage.insertData_Replace('cwsn_diff_able_json', data.cwsn_diff_able);
          })
        } else {
          this.calcDisability(data, disabily);
        };
      });
  }

  calcDisability(list, disabily: any) {
    this.cwsnDiffAbleList = [];
    disabily = disabily.split(",");
    this.cwsnDiffAbleList = list.filter((obj: any) => {
      return disabily.includes(obj.id.toString());
    });
    debugger
  }

  get classDisplay(): string {
    return this.classMap[this.Class] || '';
  }

}
